  this.bridgeDialog=document.createElement('dialog');this.bridgeDialog.id='map-bridge-dialog';this.bridgeDialog.innerHTML='<h2>Esta carretera cruza agua</h2><p>Coloca un puente compatible para sostener la carretera.</p><label>Bridge <select id="map-bridge-kind">'+options(['Wooden Bridge','Stone Bridge','Modern Bridge','Red Suspension Bridge'])+'</select></label><p id="map-bridge-summary"></p><div class="map-dialog-actions"><button data-bridge="add" class="primary">Add Bridge</button><button data-bridge="ignore">Ignore</button><button data-bridge="cancel">Cancel</button></div>';document.body.append(this.bridgeDialog);
