 beginTransform(type,p,screen,extra={}){if(this.editor.selected.some(o=>this.locked(o)||!this.shown(o)))return;const nodes=topLevelSelection(this.editor.selected);nodes.forEach(o=>o.updateWorldMatrix(true,true));const center=selectionBounds(nodes).getCenter(new THREE.Vector3());this.gesture={type,start:p,screen,center,angle:Math.atan2(p.z-center.z,p.x-center.x),matrices:nodes.map(o=>o.matrixWorld.clone()),...extra};}
